public class ShutdownExample {
    public static void main(String[] args) {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            System.out.println("Shutdown hook running: Cleaning up resources...");
        }));

        // Graceful exit: Hook will run
        // System.exit(0);

        // Brute force exit: Hook will NOT run
        Runtime.getRuntime().halt(0);
    }
}
